from docx import Document
from docx.shared import Pt, Cm
from docx.enum.text import WD_ALIGN_PARAGRAPH
from docx.oxml.ns import qn
d = Document()
s = d.sections[0]; s.page_width, s.page_height = Cm(21), Cm(29.7)
s.left_margin, s.right_margin, s.top_margin, s.bottom_margin = Cm(3), Cm(1.5), Cm(2), Cm(2)
st = d.styles['Normal']; st.font.name = 'Times New Roman'; st.font.size = Pt(14)
st.element.rPr.rFonts.set(qn('w:eastAsia'), 'Times New Roman'); st.element.rPr.rFonts.set(qn('w:cs'), 'Times New Roman')
def para(text, bold=False, align=WD_ALIGN_PARAGRAPH.JUSTIFY, indent=True, size=14, after=0, before=0, italic=False):
    p = d.add_paragraph(); f = p.paragraph_format
    f.line_spacing = 1.5; f.space_after = Pt(after); f.space_before = Pt(before); p.alignment = align
    if indent: f.first_line_indent = Cm(1.25)
    r = p.add_run(text); r.bold = bold; r.italic = italic; r.font.size = Pt(size); r.font.name = 'Times New Roman'
    return p
C = WD_ALIGN_PARAGRAPH.CENTER
para('АБСТРАКЦИОНИЗМ', True, C, False, 16)
para('ХХ ғасыр өнерінің тілін өзгерткен бағыт', False, C, False, 14, italic=True)
para('Орындағандар: Әділ Мұхтар, Сәлімгерей Қарақат', False, WD_ALIGN_PARAGRAPH.RIGHT, False, 14, after=8, before=4)
H = lambda t: para(t, True, WD_ALIGN_PARAGRAPH.LEFT, True, 14, before=6)
H('Кіріспе')
para('Абстракционизм — ХХ ғасырда бейнелеу өнерінің тілін түбегейлі өзгерткен бағыт. Ол адамды, табиғатты немесе затты дәл көрсетуден бас тартады. Мұнда пішін, сызық және түс көмекші құрал емес, шығарманың негізгі мазмұнына айналады. Термин латынның «abstractio» сөзінен шыққан, мағынасы — «алшақтау», «дерексіздену». Яғни суретші көзге көрінетін шындықтан алшақтап, көрерменге ой мен сезімді тікелей жеткізуге ұмтылады.')
H('Бағыттың бастауы')
para('Абстракционизмнің тамыры XIX ғасырға барады. Фотосурет пайда болған соң, шындықты дәл көшіру міндеті суретшінің мойнынан түсті де, кескіндеме жаңа жол іздей бастады. Импрессионистер, соның ішінде Клод Моне, заттың өзін емес, оның көзге қалдырған әсерін салды. Поль Сезанн табиғатты шар, конус және цилиндр арқылы көруге шақырды. ХХ ғасырдың басында фовизм түсті, ал кубизм пішінді еркіндікке шығарды. Осылайша сурет шындыққа ұқсауға міндетті болмай қалды.')
para('Зерттеушілердің көбі бағыттың басталуын 1910 жылдармен байланыстырады. Алайда швед суретшісі Хильма аф Клинт дерексіз картиналарын 1906 жылы-ақ сала бастаған. Оның еңбектері ондаған жылдар бойы көпшілікке беймәлім болып келді, сондықтан ол өнер тарихына кеш енді.')
H('Негізін қалаушылар')
para('Василий Кандинский (1866–1944) — абстракционизмнің негізін қалаушылардың бірі. Ол кескіндемені музыкамен салыстырып: «Түс — перне, көз — балға, ал жан — көп ішекті рояль», — деп жазды. 1911 жылы жарық көрген «Өнердегі руханилық туралы» еңбегінде түс пен пішіннің адам жанына әсерін түсіндірді. 1913 жылы салынған «VII композиция» — оның ең күрделі туындыларының бірі. Суретші «Көк салт атты» тобымен байланысты болды, кейін Баухауста сабақ берді.')
para('Казимир Малевич (1879–1935) супрематизм бағытын қалыптастырды. Ол шаршы, шеңбер, крест сияқты қарапайым геометриялық пішіндерге сүйенді. 1915 жылы Петроградтағы «0,10» көрмесінде «Қара шаршы» алғаш рет көрсетілді. Малевич оны бөлменің төргі бұрышына — әдетте икона ілінетін орынға ілді. Бүгінде «Қара шаршы» ХХ ғасыр өнерінің ең белгілі символдарының бірі саналады.')
para('Пит Мондриан (1872–1944) көлденең, тік сызықтар мен түсті тіктөртбұрыштарға негізделген тіл жасап, оны неопластицизм деп атады. Негізгі түстер — қызыл, көк, сары, оған қоса ақ фон мен қара тор оның туындыларын бірден танытады. Мондрианның идеялары «Де Стейл» тобы арқылы сәулет пен дизайнға тарады.')
H('Екі негізгі арна')
para('Абстракционизмді шартты түрде екі арнаға бөлуге болады. Біріншісі — лирикалық абстракция: онда еркін сызық, түс дағы және суретшінің сезімі басты рөл атқарады; бұл арнаның көрнекті өкілі — Кандинский. Екіншісі — геометриялық абстракция: ол қатаң пішінге, есепке және тепе-теңдікке сүйенеді; оның үлгісін Малевич пен Мондриан шығармашылығынан көреміз. Екі арна да бір мақсатты көздейді — затты бейнелемей-ақ көрерменге әсер ету.')
H('Баухаустан Нью-Йоркке дейін')
para('Германиядағы Баухаус мектебі (1919–1933) өнерді, қолөнерді және дизайнды біріктірді. Мұнда Кандинский мен Пауль Клее сабақ берді, ал нүкте, сызық және жазықтық жаңа өнердің әліппесіне айналды. 1940 жылдары абстракционизмнің орталығы Нью-Йоркке ауысып, абстрактілі экспрессионизм дүниеге келді. Джексон Поллок кенепті еденге жайып, бояуды тамызып жұмыс істеді, ал Марк Ротко үлкен түс алаңдары арқылы көрерменді терең ойға жетеледі. Наум Габо абстрактілі мүсіннің алғашқы өкілдерінің бірі болды. 1960 жылдары минимализм қарапайым пішінге ұмтылысты жалғастырса, оп-арт көзді алдайтын қозғалыс әсерін тудырды.')
H('Қазақ өнеріндегі дерексіздік')
para('Дерексіз ойлау қазақ өнеріне де жат емес. Киіз, текемет пен кілемдегі ою-өрнек — мағынаға толы таңбалар. Мысалы, «қошқар мүйіз» өрнегі байлық пен берекені білдіреді. Ал күй сөзсіз-ақ сөйлейді: домбыраның үні тыңдаушыға нақты бейнені емес, көңіл күй мен ойды жеткізеді. Бұл жағынан күй абстрактілі картинаға өте ұқсас.')
H('Қорытынды')
para('Абстрактілі туындыда нақты бейне болмайды, оның негізгі құралы — пішін, сызық және түс. Сондықтан мұндай картинаны «Не салынған?» деп емес, «Қандай әсер береді?» деп қабылдау керек. Бүгінде абстракция дизайнда, сәулетте, тіпті күнделікті заттарда өмір сүріп жатыр. Абстракционизм өнерге пішін мен түстің өзі сөйлей алатынын көрсетті.')
para('Абстрактілі картинаға қарағанда асықпаған жөн: алдымен түстердің қатынасына, сызықтың бағытына, пішіндердің ырғағына назар аударған дұрыс. Бір туынды әр адамға әртүрлі әсер қалдыруы мүмкін, және бұл — қателік емес, осы өнердің табиғаты.')
para('Абстракционизм суретшіге еркіндік, ал көрерменге өз бетінше ойлану мүмкіндігін берді. Сол себепті ол пайда болғанына жүз жылдан асса да, заманауи өнер мен дизайнның негізі болып қала береді.')
d.save('Абстракционизм-мәтін.docx')
